changeSet.sql:
ALTER TABLE lib_books
    ADD COLUMN visibility VARCHAR(20) NOT NULL DEFAULT 'PUBLIC';

ALTER TABLE lib_books
    ADD CONSTRAINT lib_books_visibility_check
    CHECK (visibility IN ('PRIVATE', 'SHARED', 'PUBLIC'));

CREATE INDEX idx_lib_books_visibility ON lib_books(visibility);
CREATE INDEX idx_lib_books_created_by_visibility
    ON lib_books(created_by, visibility);

CREATE TABLE lib_book_members (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    book_id    UUID NOT NULL REFERENCES lib_books(id) ON DELETE CASCADE,
    user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role       VARCHAR(20) NOT NULL,
    added_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    added_by   UUID NOT NULL REFERENCES users(id),
    CONSTRAINT lib_book_members_role_check
        CHECK (role IN ('MEMBER', 'EDITOR')),
    CONSTRAINT lib_book_members_unique
        UNIQUE (book_id, user_id)
);

CREATE INDEX idx_lib_book_members_user ON lib_book_members(user_id);
CREATE INDEX idx_lib_book_members_book ON lib_book_members(book_id);

rollback.sql:
DROP INDEX IF EXISTS idx_lib_book_members_book;
DROP INDEX IF EXISTS idx_lib_book_members_user;
DROP TABLE IF EXISTS lib_book_members;

DROP INDEX IF EXISTS idx_lib_books_created_by_visibility;
DROP INDEX IF EXISTS idx_lib_books_visibility;
ALTER TABLE lib_books DROP CONSTRAINT IF EXISTS lib_books_visibility_check;
ALTER TABLE lib_books DROP COLUMN visibility;
